file.interface:
id: string; name: string; chipset: string; chipsetFolder: string;
firehoseUrls?: { programmer: string; digest?: string; signature?: string };
status: 'tested' | 'beta' | 'coming'

selectedDevice: DeviceProfile | null; isConnected: boolean;
connectionError: string | null; firehoseLoaded: boolean;
setDevice, setConnected, setFirehoseLoaded, setError, reset

interface.signature:
function useFirehoseLoader(): {
  loadFirehose: (device: DeviceProfile) => Promise<void>;
  status: 'idle' | 'loading' | 'success' | 'error';
  progress: { loaded: number; total: number; currentFile: string };
  error: string | null;
  showManualPopup: boolean;
  setShowManualPopup: (show: boolean) => void;
}

interface FirehoseFiles {
  programmer: ArrayBuffer;
  digest: ArrayBuffer;
  signature: ArrayBuffer;
}

urlConstruction.example:
const device = deviceStore.selectedDevice;
const urls = {
  programmer: device.firehose.programmerUrl,
  digest: device.firehose.digestUrl,
  signature: device.firehose.signatureUrl
};

cachingStrategy.example:
// Module-level cache
const firehoseCache = new Map<string, FirehoseFiles>();

// Check cache before fetching
const cached = firehoseCache.get(device.chipset);
if (cached) return cached;
